function renderStats(){const n=document.getElementById("stats-grid");n&&"undefined"!=typeof MENAL_INFO&&(n.innerHTML=MENAL_INFO.quickStats.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon">${n.icon}</span>\n            <div class="stat-val">${n.value}</div>\n            <div class="stat-lbl">${n.label}</div>\n        </div>\n    `).join(""))}function renderSpots(){const n=document.getElementById("spots-grid");n&&"undefined"!=typeof NATURE_HERITAGE_SPOTS&&(n.innerHTML=NATURE_HERITAGE_SPOTS.map(n=>`\n        <div class="spot-card">\n            <span class="spot-cat-tag">${n.category}</span>\n            <h3>✨ ${n.title}</h3>\n            <p>${n.description}</p>\n            <p class="spot-sig"><strong>Historical / Ecological Context:</strong> ${n.significance}</p>\n        </div>\n    `).join(""))}function renderSeasonalData(){const n=document.getElementById("seasonal-grid");n&&"undefined"!=typeof SEASONAL_DATA&&(n.innerHTML=SEASONAL_DATA.map(n=>`\n        <div class="season-card">\n            <h3>🌧️ ${n.season}</h3>\n            <span class="flow-tag">${n.flow}</span>\n            <p>${n.description}</p>\n        </div>\n    `).join(""))}function renderAttractions(){const n=document.getElementById("attractions-grid");n&&"undefined"!=typeof NEARBY_ATTRACTIONS&&(n.innerHTML=NEARBY_ATTRACTIONS.map(n=>`\n        <div class="attraction-card">\n            <h3>📍 ${n.name}</h3>\n            <span class="dist-tag">${n.distance} from Menal</span>\n            <p>${n.description}</p>\n        </div>\n    `).join(""))}function renderGallery(){const n=document.getElementById("gallery-grid");n&&"undefined"!=typeof GALLERY_IMAGES&&(n.innerHTML=GALLERY_IMAGES.map(n=>`\n        <div class="gallery-card">\n            <img src="${n.url}" alt="${n.caption}" loading="lazy" />\n            <p>${n.caption}</p>\n        </div>\n    `).join(""))}function renderReferences(){const n=document.getElementById("references-list");n&&"undefined"!=typeof REFERENCES&&(n.innerHTML=REFERENCES.map(n=>`\n        <li>\n            <a href="${n.link}" target="_blank" rel="noopener noreferrer">📚 ${n.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const n=document.getElementById("theme-toggle");n&&n.addEventListener("click",()=>{const e=document.body.classList.toggle("light-theme");localStorage.setItem("theme",e?"light":"dark"),n.textContent=e?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderSpots(),renderSeasonalData(),renderAttractions(),renderGallery(),renderReferences(),initThemeToggle()});